define AFPass [Ctx([[EnglishStarAlphabet]*])];
define AFUL [Ctx([
    {*u} -> {*o}, {*ú} -> {*ó} ||
    .#. EnglishStarConsonant* _
    [EnglishStarConsonantNoJ - EnglishStarNasal]
    EnglishStarConsonantNoJ* [EnglishStarNonHighVowel | {*ǭ}]
])];
define AFInput [
    EnglishProtoInput |
    [{ᵘ}:{*ᵘ}|{ᶜ}:{*ᶜ}|0]
    [pgrmStrongPlainHeavy | pgrmStrongPlainHeavyPrefixed |
     pgrmStrongNasal | pgrmStrongNasalPrefixed] ǭ:{*ǭ}
];
